// Flag-off parity of the shared headers MPX_BROWSE_V2 touched, against BASE (2ffd5c14 = 2164c4ad + w9 de8d3d17)
// (coregate v2.3). The base copies are generated by test_browse_flagoff_parity.sh as
// build/.../base/{library_browser,input_mailbox}_base.hpp in namespace misterplex_base:
//   renderLibraryI420     byte-identical frames (every printable title character, both row
//                         kinds, statuses, cursor positions, 4 rasters)
//   parseLibraryXml       identical rows on PMS-shaped and helper-shaped XML
//   LibraryBrowser        identical state after random show/move/push/pop sequences
//   decodeInputMailboxWord (default limit), InputMailboxEdgeDetector, mapPlaybackCommand,
//                         dispatchPlaybackCommand: identical on random words / commands 0-5
#include "libmisterplex/input_mailbox.hpp"
#include "libmisterplex/library_browser.hpp"

#include "input_mailbox_base.hpp"
#include "library_browser_base.hpp"

#include <cstdio>
#include <random>
#include <string>
#include <vector>

namespace {
int g_checks = 0;
int g_fail = 0;
#define CHECK(cond, ...)                                                                    \
    do {                                                                                    \
        ++g_checks;                                                                         \
        if (!(cond)) {                                                                      \
            ++g_fail;                                                                       \
            std::fprintf(stderr, "FAIL %s:%d: %s: ", __FILE__, __LINE__, #cond);          \
            std::fprintf(stderr, __VA_ARGS__);                                              \
            std::fprintf(stderr, "\n");                                                     \
        }                                                                                   \
    } while (0)

template <typename Row>
std::vector<Row> rowsFor(std::mt19937& rng, int n) {
    std::vector<Row> rows;
    for (int i = 0; i < n; ++i) {
        Row r;
        std::string t;
        const int len = static_cast<int>(rng() % 70);
        for (int k = 0; k < len; ++k)
            t += static_cast<char>(32 + rng() % 95);
        r.title = t;
        r.key = std::to_string(i);
        r.ratingKey = std::to_string(1000 + i);
        r.directory = (rng() % 2) == 0;
        rows.push_back(r);
    }
    return rows;
}

void testRender() {
    std::mt19937 rng(42);
    const std::vector<std::pair<int, int>> sizes = {{640, 480}, {320, 240}, {624, 480}, {1280, 720}};
    int frames = 0;
    for (const auto& wh : sizes) {
        for (int iter = 0; iter < 25; ++iter) {
            const int n = static_cast<int>(rng() % 40);
            misterplex::LibraryBrowser a;
            misterplex_base::LibraryBrowser b;
            std::mt19937 r1(iter * 7 + wh.first), r2(iter * 7 + wh.first);
            const auto ra = rowsFor<misterplex::LibraryRow>(r1, n);
            const auto rb = rowsFor<misterplex_base::LibraryRow>(r2, n);
            const std::string status = (iter % 3 == 0) ? "" : (iter % 3 == 1 ? "fetch failed" : "no plex token");
            a.show(ra, status);
            b.show(rb, status);
            if (iter % 5 == 4) {
                a.visible = false;
                b.visible = false;
            }
            const int moves = static_cast<int>(rng() % 50);
            for (int m = 0; m < moves; ++m) {
                a.move(1);
                b.move(1);
            }
            const size_t sz = static_cast<size_t>(wh.first) * wh.second * 3 / 2;
            std::vector<uint8_t> fa(sz, 0x33), fb(sz, 0x33);
            misterplex::renderLibraryI420(fa.data(), wh.first, wh.second, a);
            misterplex_base::renderLibraryI420(fb.data(), wh.first, wh.second, b);
            CHECK(fa == fb, "frame differs %dx%d iter %d", wh.first, wh.second, iter);
            ++frames;
        }
    }
    // Every printable character through the V1 glyph table, both inks.
    for (int c = 32; c < 127; ++c) {
        CHECK(std::equal(misterplex::libraryGlyph(static_cast<char>(c)),
                         misterplex::libraryGlyph(static_cast<char>(c)) + 7,
                         misterplex_base::libraryGlyph(static_cast<char>(c))),
              "glyph %d", c);
    }
    std::printf("  render: %d frames byte-identical; glyph table identical\n", frames);
}

void testParse() {
    const char* docs[] = {
        "<MediaContainer><Directory key=\"1\" type=\"movie\" title=\"Movies &amp; Docs\"/>"
        "<Directory key=\"2\" title=\"TV\"/></MediaContainer>",
        "<MediaContainer><Video ratingKey=\"5\" key=\"/library/metadata/5\" title=\"X\" "
        "viewOffset=\"6\"/><Directory key=\"/a\" title=\"D\"/><Track ratingKey=\"9\" title=\"T\"/>"
        "<Video title=\"\" key=\"\" ratingKey=\"\"/></MediaContainer>",
        "<MediaContainer><Video title=\"S01E03\" ratingKey=\"115463\" mpxServer=\"s1\" "
        "mpxSource=\"ladder\" mpxOffsetMs=\"221000\" key=\"/menu/resolve/s1/115463\"/>"
        "<Directory title=\"NEXT &gt;\" key=\"/menu/section/s/2/all?page=2&amp;cols=30\" "
        "type=\"mpxpage\"/></MediaContainer>",
        "", "<", "<Directory title=\"x", "<Video ratingKey=\"1\" grandparentKey=\"/g\" key=\"/k\">",
    };
    for (const char* d : docs) {
        const auto a = misterplex::parseLibraryXml(d);
        const auto b = misterplex_base::parseLibraryXml(d);
        bool same = a.size() == b.size();
        for (size_t i = 0; same && i < a.size(); ++i)
            same = a[i].title == b[i].title && a[i].key == b[i].key &&
                   a[i].ratingKey == b[i].ratingKey && a[i].type == b[i].type &&
                   a[i].directory == b[i].directory &&
                   misterplex::libraryListPath(a[i]) == misterplex_base::libraryListPath(b[i]);
        CHECK(same, "parseLibraryXml differs on '%.40s'", d);
        for (const auto& r : a)
            CHECK(!r.fromMenu && r.mpxSource.empty() && !r.offsetPresent,
                  "V1 parse sets no V2 field");
    }
}

void testBrowserOps() {
    std::mt19937 rng(7);
    for (int iter = 0; iter < 200; ++iter) {
        misterplex::LibraryBrowser a;
        misterplex_base::LibraryBrowser b;
        for (int step = 0; step < 40; ++step) {
            const int op = static_cast<int>(rng() % 6);
            const int n = static_cast<int>(rng() % 30);
            std::mt19937 r1(iter * 100 + step), r2(iter * 100 + step);
            switch (op) {
            case 0:
                a.show(rowsFor<misterplex::LibraryRow>(r1, n), "s");
                b.show(rowsFor<misterplex_base::LibraryRow>(r2, n), "s");
                break;
            case 1:
                a.push(rowsFor<misterplex::LibraryRow>(r1, n));
                b.push(rowsFor<misterplex_base::LibraryRow>(r2, n));
                break;
            case 2:
                CHECK(a.pop() == b.pop(), "pop");
                break;
            case 3: {
                const int d = static_cast<int>(rng() % 9) - 4;
                a.move(d);
                b.move(d);
                break;
            }
            case 4:
                a.hide();
                b.hide();
                break;
            default:
                a.clamp();
                b.clamp();
            }
            const auto* ca = a.current();
            const auto* cb = b.current();
            CHECK(a.visible == b.visible && a.stack.size() == b.stack.size() &&
                      a.cursors == b.cursors && a.status == b.status && a.empty() == b.empty() &&
                      a.cursor() == b.cursor() && (ca == nullptr) == (cb == nullptr) &&
                      (!ca || (ca->title == cb->title && ca->key == cb->key)),
                  "browser state differs iter %d step %d", iter, step);
        }
    }
}

struct Transport {
    std::vector<std::string> calls;
    void pause() { calls.push_back("pause"); }
    void resume() { calls.push_back("resume"); }
    void stop() { calls.push_back("stop"); }
    void seekMs(int64_t ms) { calls.push_back("seek " + std::to_string(ms)); }
};

void testMailbox() {
    std::mt19937_64 rng(1004);
    int words = 0;
    misterplex::InputMailboxEdgeDetector ea;
    misterplex_base::InputMailboxEdgeDetector eb;
    for (int i = 0; i < 200000; ++i) {
        uint64_t w = rng();
        if (i % 3 != 0)
            w = (w & ~0xFFFFFFFFull) | misterplex::kInputMailboxMagic;
        if (i % 5 == 0) // small commands dominate
            w = (w & ~(0xFFull << 32)) | (static_cast<uint64_t>(rng() % 14) << 32);
        misterplex::InputMailboxSample sa;
        misterplex_base::InputMailboxSample sb;
        const bool ra = misterplex::decodeInputMailboxWord(w, sa);
        const bool rb = misterplex_base::decodeInputMailboxWord(w, sb);
        CHECK(ra == rb, "decode result differs for %016llx", static_cast<unsigned long long>(w));
        if (ra && rb) {
            CHECK(static_cast<int>(sa.command) == static_cast<int>(sb.command) && sa.seq == sb.seq &&
                      sa.cmdSeq == sb.cmdSeq,
                  "decode fields differ");
            misterplex::PlaybackCommand ca;
            misterplex_base::PlaybackCommand cb;
            CHECK(ea.accept(sa, ca) == eb.accept(sb, cb) &&
                      static_cast<int>(ca) == static_cast<int>(cb),
                  "edge detector differs");
        } else {
            ea.noteNoValidWord();
            eb.noteNoValidWord();
        }
        ++words;
    }
    for (int c = 0; c <= 5; ++c)
        for (int playing = 0; playing < 2; ++playing)
            for (int paused = 0; paused < 2; ++paused)
                for (int64_t pos : {-5LL, 0LL, 5000LL, 60000LL, 70000LL}) {
                    const auto a = misterplex::mapPlaybackCommand(
                        static_cast<misterplex::PlaybackCommand>(c), playing, paused, pos, 60000,
                        30000, 10000);
                    const auto b = misterplex_base::mapPlaybackCommand(
                        static_cast<misterplex_base::PlaybackCommand>(c), playing, paused, pos, 60000,
                        30000, 10000);
                    CHECK(static_cast<int>(a.kind) == static_cast<int>(b.kind) &&
                              a.seekTargetMs == b.seekTargetMs,
                          "map cmd %d", c);
                    Transport ta, tb;
                    const misterplex::PlaybackTransportState sa{playing != 0, paused != 0, pos, 60000};
                    const misterplex_base::PlaybackTransportState sb{playing != 0, paused != 0, pos,
                                                                     60000};
                    (void)misterplex::dispatchPlaybackCommand(
                        static_cast<misterplex::PlaybackCommand>(c), sa, 30000, 10000, 100, 50, ta);
                    (void)misterplex_base::dispatchPlaybackCommand(
                        static_cast<misterplex_base::PlaybackCommand>(c), sb, 30000, 10000, 100, 50, tb);
                    CHECK(ta.calls == tb.calls, "dispatch cmd %d", c);
                }
    std::printf("  mailbox: %d words decoded and edge-detected identically; commands 0-5 map "
                "and dispatch identically\n",
                words);
}
} // namespace

int main() {
    testRender();
    testParse();
    testBrowserOps();
    testMailbox();
    if (g_fail) {
        std::printf("test_browse_flagoff_parity: %d FAIL of %d checks\n", g_fail, g_checks);
        return 1;
    }
    std::printf("test_browse_flagoff_parity: OK (%d checks vs the BASE headers)\n", g_checks);
    return 0;
}
